def __repr__(self):
    from .utils._pprint import _EstimatorPrettyPrinter

    N_CHAR_MAX = 700  # number of non-whitespace or newline chars
    N_MAX_ELEMENTS_TO_SHOW = 30  # number of elements to show in sequences

    # use ellipsis for sequences with a lot of elements
    pp = _EstimatorPrettyPrinter(
        compact=True, indent=1, indent_at_name=True,
        n_max_elements_to_show=N_MAX_ELEMENTS_TO_SHOW)

    repr_ = pp.pformat(self)

    # Use bruteforce ellipsis if string is very long. Count non-blank
    # characters at both ends so that indentation does not consume the
    # character budget and hide the structure of nested estimators.
    if len(''.join(repr_.split())) > N_CHAR_MAX:
        lim = N_CHAR_MAX // 2
        pattern = r'^(\s*\S){%d}' % lim
        left_lim = re.match(pattern, repr_).end()
        right_lim = len(repr_) - re.match(pattern, repr_[::-1]).end()

        if '\n' in repr_[left_lim:right_lim]:
            # Keep the full line and indentation at the start of the
            # suffix, rather than joining two unrelated parameter lines.
            right_lim = repr_.rfind('\n', 0, right_lim)

        # Extending the suffix to a full line may leave nothing to omit.
        if left_lim + len('...') < right_lim:
            repr_ = repr_[:left_lim] + '...' + repr_[right_lim:]
    return repr_

