def test_length_constraint_boundary():
    class Estimator(BaseEstimator):
        def __init__(self, value):
            self.value = value

    # Inserting an ellipsis should only shorten the representation.
    overhead = len("Estimator(value='')")
    for length in (699, 700, 701, 703, 704, 1000):
        value = 'x' * (length - overhead)
        full_repr = "Estimator(value='%s')" % value
        expected = (full_repr if length <= 703 else
                    full_repr[:350] + '...' + full_repr[-350:])
        assert repr(Estimator(value)) == expected


